CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'client' CHECK (role IN ('client','admin')));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_support_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'admin') $$;
REVOKE ALL ON FUNCTION public.is_support_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_support_admin() TO authenticated;
CREATE POLICY roles_self ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid() OR public.is_support_admin());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_support_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES (NEW.id, left(coalesce(NEW.raw_user_meta_data->>'display_name',''),100)); INSERT INTO public.user_roles(user_id,role) VALUES (NEW.id,'client'); RETURN NEW; END $$;
CREATE TRIGGER support_profile_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_support_profile();
CREATE TABLE public.support_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.profiles(id), title text NOT NULL CHECK (length(title) BETWEEN 3 AND 160), description text NOT NULL CHECK (length(description) BETWEEN 3 AND 5000), kind text NOT NULL CHECK (kind IN ('helpdesk','service')), priority text NOT NULL DEFAULT 'normal' CHECK (priority IN ('low','normal','high')), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted','in_progress','waiting','resolved','declined')), progress integer NOT NULL DEFAULT 0 CHECK (progress BETWEEN 0 AND 100), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.support_requests TO authenticated; GRANT ALL ON public.support_requests TO service_role;
ALTER TABLE public.support_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY requests_read ON public.support_requests FOR SELECT TO authenticated USING (client_id = auth.uid() OR public.is_support_admin());
CREATE POLICY requests_create ON public.support_requests FOR INSERT TO authenticated WITH CHECK (client_id = auth.uid() AND status = 'pending' AND progress = 0);
CREATE POLICY requests_admin_update ON public.support_requests FOR UPDATE TO authenticated USING (public.is_support_admin()) WITH CHECK (public.is_support_admin());
CREATE TABLE public.support_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.support_requests(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES public.profiles(id), body text NOT NULL CHECK (length(body) BETWEEN 1 AND 5000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.support_messages TO authenticated; GRANT ALL ON public.support_messages TO service_role;
ALTER TABLE public.support_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_read ON public.support_messages FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.support_requests r WHERE r.id = request_id AND (r.client_id = auth.uid() OR public.is_support_admin())));
CREATE POLICY messages_send ON public.support_messages FOR INSERT TO authenticated WITH CHECK (sender_id = auth.uid() AND EXISTS (SELECT 1 FROM public.support_requests r WHERE r.id = request_id AND (r.client_id = auth.uid() OR public.is_support_admin())));
CREATE TABLE public.support_updates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.support_requests(id) ON DELETE CASCADE, body text NOT NULL CHECK (length(body) BETWEEN 1 AND 5000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.support_updates TO authenticated; GRANT ALL ON public.support_updates TO service_role;
ALTER TABLE public.support_updates ENABLE ROW LEVEL SECURITY;
CREATE POLICY updates_read ON public.support_updates FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.support_requests r WHERE r.id = request_id AND (r.client_id = auth.uid() OR public.is_support_admin())));
CREATE POLICY updates_admin ON public.support_updates FOR INSERT TO authenticated WITH CHECK (public.is_support_admin());
CREATE TABLE public.support_calls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.support_requests(id) ON DELETE CASCADE, scheduled_at timestamptz NOT NULL, url text NOT NULL CHECK (url ~ '^https://(meet.google.com/|calendly.com/)'), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.support_calls TO authenticated; GRANT ALL ON public.support_calls TO service_role;
ALTER TABLE public.support_calls ENABLE ROW LEVEL SECURITY;
CREATE POLICY calls_read ON public.support_calls FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.support_requests r WHERE r.id = request_id AND (r.client_id = auth.uid() OR public.is_support_admin())));
CREATE POLICY calls_admin ON public.support_calls FOR INSERT TO authenticated WITH CHECK (public.is_support_admin());
CREATE INDEX requests_client ON public.support_requests(client_id,created_at); CREATE INDEX messages_request ON public.support_messages(request_id,created_at); CREATE INDEX updates_request ON public.support_updates(request_id,created_at); CREATE INDEX calls_request ON public.support_calls(request_id,scheduled_at);